/*
 * WHATWG Encoding Standard: labels, streaming decoders and the document sniffing algorithm
 * (sniff.c has the prescan; this file has the label table and the decoders).
 *
 * The label table and the single-byte index tables are generated by tools/unicodegen/encgen.c into
 * encoding_tables.inc. CJK encodings are listed with kind EMBI_ENC_UNSUPPORTED (see W7 scope).
 */
#include "loader/loader.h"

#include <string.h>

#include "encoding_tables.inc"

#define ENC_COUNT (sizeof embi_enc_defs / sizeof embi_enc_defs[0])
#define REPLACEMENT_CP 0xFFFDu

static bool is_html_ws(unsigned char c)
{
    return c == ' ' || c == '\t' || c == '\n' || c == '\f' || c == '\r';
}

const embi_encoding *embi_encoding_named(const char *name)
{
    for (size_t i = 0; i < ENC_COUNT; i++) {
        if (strcmp(embi_enc_defs[i].name, name) == 0) {
            return &embi_enc_defs[i];
        }
    }
    return nullptr;
}

const embi_encoding *embi_encoding_for_label(embi_str label)
{
    const unsigned char *p = (const unsigned char *)label.ptr;
    size_t n = label.len;
    if (p == nullptr) {
        return nullptr;
    }
    while (n > 0 && is_html_ws(p[0])) {
        p++;
        n--;
    }
    while (n > 0 && is_html_ws(p[n - 1])) {
        n--;
    }
    if (n == 0) {
        return nullptr;
    }
    embi_str s = {(const char *)p, (uint32_t)n};
    for (size_t e = 0; e < ENC_COUNT; e++) {
        const char *w = embi_enc_defs[e].labels;
        for (;;) {
            const char *end = strchr(w, ' ');
            size_t wl = end != nullptr ? (size_t)(end - w) : strlen(w);
            if (embi_str_ieq(s, (embi_str){w, (uint32_t)wl})) {
                return &embi_enc_defs[e];
            }
            if (end == nullptr) {
                break;
            }
            w = end + 1;
        }
    }
    return nullptr;
}

const char *embi_encoding_label_name(const unsigned char *p, size_t n)
{
    if (p == nullptr) {
        return nullptr;
    }
    const embi_encoding *e = embi_encoding_for_label((embi_str){(const char *)p, (uint32_t)n});
    return e != nullptr ? e->name : nullptr;
}

/* ------------------------------------------------------------------ decoders */

void embi_decoder_init(embi_decoder *d, const embi_encoding *enc, bool fatal, bool ignore_bom)
{
    *d = (embi_decoder){
        .enc = enc,
        .fatal = fatal,
        .ignore_bom = ignore_bom,
        .lead_byte = -1,
    };
}

/* The BOM that starts a stream for an encoding, or 0 bytes when it has none. */
static unsigned bom_length(embi_enc_kind kind)
{
    switch (kind) {
    case EMBI_ENC_UTF8:
        return 3;
    case EMBI_ENC_UTF16LE:
    case EMBI_ENC_UTF16BE:
        return 2;
    default:
        return 0;
    }
}

static const unsigned char *bom_bytes(embi_enc_kind kind)
{
    static const unsigned char utf8[3] = {0xEF, 0xBB, 0xBF};
    static const unsigned char le[2] = {0xFF, 0xFE};
    static const unsigned char be[2] = {0xFE, 0xFF};
    switch (kind) {
    case EMBI_ENC_UTF8:
        return utf8;
    case EMBI_ENC_UTF16LE:
        return le;
    default:
        return be;
    }
}

/* Emits one error: U+FFFD, or a failure in fatal mode. Returns false when decoding must stop. */
static bool decode_error(embi_decoder *d, embi_sb *out)
{
    if (d->fatal) {
        d->failed = true;
        return false;
    }
    embi_sb_append_cp(out, REPLACEMENT_CP);
    return true;
}

static bool feed_utf8(embi_decoder *d, const unsigned char *p, size_t n, embi_sb *out)
{
    size_t k = 0;
    while (k < n) {
        unsigned b = p[k];
        if (d->needed == 0) {
            k++;
            if (b <= 0x7F) {
                embi_sb_append_char(out, (char)b);
                continue;
            }
            d->lower = 0x80;
            d->upper = 0xBF;
            if (b >= 0xC2 && b <= 0xDF) {
                d->needed = 1;
                d->cp = b & 0x1Fu;
            } else if (b >= 0xE0 && b <= 0xEF) {
                if (b == 0xE0) {
                    d->lower = 0xA0;
                }
                if (b == 0xED) {
                    d->upper = 0x9F;
                }
                d->needed = 2;
                d->cp = b & 0xFu;
            } else if (b >= 0xF0 && b <= 0xF4) {
                if (b == 0xF0) {
                    d->lower = 0x90;
                }
                if (b == 0xF4) {
                    d->upper = 0x8F;
                }
                d->needed = 3;
                d->cp = b & 0x7u;
            } else {
                if (!decode_error(d, out)) {
                    return false;
                }
                continue;
            }
            d->seen = 0;
            continue;
        }
        if (b < d->lower || b > d->upper) {
            /* The byte is not part of the sequence: reset and reprocess it as a lead byte. */
            d->cp = 0;
            d->needed = 0;
            d->seen = 0;
            if (!decode_error(d, out)) {
                return false;
            }
            continue;
        }
        d->lower = 0x80;
        d->upper = 0xBF;
        d->cp = (d->cp << 6) | (b & 0x3Fu);
        d->seen++;
        k++;
        if (d->seen == d->needed) {
            embi_sb_append_cp(out, d->cp);
            d->cp = 0;
            d->needed = 0;
            d->seen = 0;
        }
    }
    return true;
}

static bool feed_utf16(embi_decoder *d, const unsigned char *p, size_t n, bool be, embi_sb *out)
{
    for (size_t k = 0; k < n; k++) {
        if (d->lead_byte < 0) {
            d->lead_byte = p[k];
            continue;
        }
        uint32_t unit = be ? ((uint32_t)d->lead_byte << 8 | p[k]) : ((uint32_t)p[k] << 8 | (uint32_t)d->lead_byte);
        d->lead_byte = -1;
        if (d->lead_surrogate != 0) {
            if (unit >= 0xDC00u && unit <= 0xDFFFu) {
                uint32_t cp = 0x10000u + ((d->lead_surrogate - 0xD800u) << 10) + (unit - 0xDC00u);
                d->lead_surrogate = 0;
                embi_sb_append_cp(out, cp);
                continue;
            }
            /* An unpaired high surrogate: report it, then decode this unit normally. */
            d->lead_surrogate = 0;
            if (!decode_error(d, out)) {
                return false;
            }
        }
        if (unit >= 0xD800u && unit <= 0xDBFFu) {
            d->lead_surrogate = unit;
        } else if (unit >= 0xDC00u && unit <= 0xDFFFu) {
            if (!decode_error(d, out)) {
                return false;
            }
        } else {
            embi_sb_append_cp(out, unit);
        }
    }
    return true;
}

static bool feed_body(embi_decoder *d, const unsigned char *p, size_t n, embi_sb *out)
{
    const embi_encoding *e = d->enc;
    switch (e->kind) {
    case EMBI_ENC_UTF8:
        return feed_utf8(d, p, n, out);
    case EMBI_ENC_UTF16LE:
        return feed_utf16(d, p, n, false, out);
    case EMBI_ENC_UTF16BE:
        return feed_utf16(d, p, n, true, out);
    case EMBI_ENC_SINGLE:
        for (size_t k = 0; k < n; k++) {
            unsigned b = p[k];
            if (b < 0x80) {
                embi_sb_append_char(out, (char)b);
            } else {
                uint32_t cp = e->index[b - 0x80];
                if (cp == 0xFFFDu) {
                    /* An index hole is an error (a throw for a fatal decoder). */
                    if (!decode_error(d, out)) {
                        return false;
                    }
                } else {
                    embi_sb_append_cp(out, cp);
                }
            }
        }
        return true;
    case EMBI_ENC_USER_DEFINED:
        for (size_t k = 0; k < n; k++) {
            unsigned b = p[k];
            if (b < 0x80) {
                embi_sb_append_char(out, (char)b);
            } else {
                embi_sb_append_cp(out, 0xF780u + (b - 0x80u));
            }
        }
        return true;
    case EMBI_ENC_REPLACEMENT:
        /* The replacement decoder reports one error for the whole stream. */
        if (n > 0 && !d->replacement_done) {
            d->replacement_done = true;
            return decode_error(d, out);
        }
        return true;
    case EMBI_ENC_UNSUPPORTED:
        /* Callers reject unsupported encodings first. Treat the stream as undecodable. */
        return decode_error(d, out);
    }
    return true;
}

static bool feed_flush(embi_decoder *d, embi_sb *out)
{
    switch (d->enc->kind) {
    case EMBI_ENC_UTF8:
        if (d->needed != 0) {
            d->cp = 0;
            d->needed = 0;
            d->seen = 0;
            return decode_error(d, out);
        }
        return true;
    case EMBI_ENC_UTF16LE:
    case EMBI_ENC_UTF16BE:
        if (d->lead_byte >= 0 || d->lead_surrogate != 0) {
            d->lead_byte = -1;
            d->lead_surrogate = 0;
            return decode_error(d, out);
        }
        return true;
    default:
        return true;
    }
}

static bool decode_inner(embi_decoder *d, const unsigned char *p, size_t n, bool flush, embi_sb *out)
{
    if (d->failed) {
        return false;
    }
    size_t k = 0;
    if (!d->started) {
        unsigned bl = bom_length(d->enc->kind);
        if (d->ignore_bom || bl == 0) {
            d->started = true;
        } else {
            const unsigned char *bom = bom_bytes(d->enc->kind);
            while (k < n && d->head_len < bl) {
                d->head[d->head_len++] = p[k++];
                if (memcmp(d->head, bom, d->head_len) != 0) {
                    d->started = true;
                    break;
                }
            }
            if (!d->started && d->head_len == bl) {
                /* The BOM is complete: it is dropped. */
                d->head_len = 0;
                d->started = true;
            } else if (!d->started && flush) {
                /* Fewer bytes than a BOM, at the end of the stream: they are data. */
                d->started = true;
            }
            if (d->started && d->head_len > 0) {
                /* Bytes held back for a BOM that did not match are data. */
                if (!feed_body(d, d->head, d->head_len, out)) {
                    return false;
                }
                d->head_len = 0;
            }
        }
    }
    if (d->started && k < n) {
        if (!feed_body(d, p + k, n - k, out)) {
            return false;
        }
    }
    if (flush) {
        if (!feed_flush(d, out)) {
            return false;
        }
        /* The decoder is ready for a new stream after a flush. */
        d->started = false;
        d->head_len = 0;
        d->failed = false;
        d->replacement_done = false;
    }
    return true;
}

bool embi_decode(embi_decoder *d, const unsigned char *p, size_t n, bool flush, embi_sb *out)
{
    bool ok = decode_inner(d, p, n, flush, out);
    if (flush) {
        /* The end of a stream, also after a fatal error: ready for the next stream. */
        embi_decoder_init(d, d->enc, d->fatal, d->ignore_bom);
    }
    return ok;
}

/* ------------------------------------------------------------------ encoders */

bool embi_encode_single(const embi_encoding *enc, uint32_t cp, uint8_t *byte)
{
    if (cp < 0x80u) {
        *byte = (uint8_t)cp;
        return true;
    }
    if (enc->kind == EMBI_ENC_USER_DEFINED) {
        if (cp >= 0xF780u && cp <= 0xF7FFu) {
            *byte = (uint8_t)(cp - 0xF780u + 0x80u);
            return true;
        }
        return false;
    }
    if (enc->kind != EMBI_ENC_SINGLE || cp == REPLACEMENT_CP) {
        /* U+FFFD marks the holes of an index, so it is never an encodable code point. */
        return false;
    }
    for (unsigned i = 0; i < 128; i++) {
        if (enc->index[i] == cp) {
            *byte = (uint8_t)(0x80u + i);
            return true;
        }
    }
    return false;
}

bool embi_encode(const embi_encoding *enc, embi_str utf8, bool html_errors, embi_sb *out)
{
    if (enc == nullptr || enc->kind == EMBI_ENC_UNSUPPORTED) {
        return false;
    }
    if (enc->kind != EMBI_ENC_SINGLE && enc->kind != EMBI_ENC_USER_DEFINED) {
        /* UTF-8, and the encodings whose encoder is UTF-8 (UTF-16, replacement). Invalid input
         * cannot occur in a UTF-8 string, but a lone byte is replaced rather than copied. */
        const char *p = utf8.ptr;
        const char *e = embi_str_end(utf8);
        while (p < e) {
            embi_sb_append_cp(out, embi_utf8_decode(&p, e));
        }
        return true;
    }
    const char *p = utf8.ptr;
    const char *e = embi_str_end(utf8);
    bool ok = true;
    while (p < e) {
        uint32_t cp = embi_utf8_decode(&p, e);
        uint8_t b;
        if (embi_encode_single(enc, cp, &b)) {
            embi_sb_append_char(out, (char)b);
        } else if (html_errors) {
            embi_sb_append(out, EMBI_STR("&#"));
            embi_sb_append_u64(out, cp);
            embi_sb_append_char(out, ';');
        } else {
            ok = false;
            break;
        }
    }
    return ok;
}
